{
  "decision-choose-same-day-reimbursement-batch": "WITH ready AS (SELECT voucher_id, principal_cents, principal_cents + fee_cents AS cost FROM voucher WHERE stage = 'ready'), batches AS (SELECT voucher_id AS first_id, NULL AS second_id, principal_cents, cost AS cash_used_cents, 1 AS voucher_count FROM ready UNION ALL SELECT a.voucher_id, b.voucher_id, a.principal_cents + b.principal_cents, a.cost + b.cost, 2 FROM ready AS a JOIN ready AS b ON a.voucher_id COLLATE BINARY < b.voucher_id) SELECT first_id, second_id, principal_cents, cash_used_cents FROM batches WHERE cash_used_cents <= (SELECT cash_cents FROM run_limit) ORDER BY voucher_count DESC, principal_cents DESC, first_id COLLATE BINARY, second_id COLLATE BINARY LIMIT 1",
  "decision-choose-two-recovery-retrofits": "WITH eligible AS (SELECT kit_code, lift_bay, fit_hours, proposed_grams - existing_grams AS gain FROM retrofit_trials WHERE proposed_grams IS NOT NULL AND existing_grams IS NOT NULL) SELECT a.kit_code AS first_code, b.kit_code AS second_code, a.gain + b.gain AS gained_grams, a.fit_hours + b.fit_hours AS install_hours FROM eligible AS a JOIN eligible AS b ON a.kit_code COLLATE BINARY < b.kit_code AND a.lift_bay <> b.lift_bay WHERE a.fit_hours + b.fit_hours <= 8 ORDER BY gained_grams DESC, install_hours, first_code COLLATE BINARY, second_code COLLATE BINARY LIMIT 1",
  "decision-citation-footnote-duplicate-lineages": "WITH RECURSIVE reach(note_id, ancestor) AS (SELECT note_id, note_id FROM review_notes UNION SELECT r.note_id, c.source_note FROM reach AS r JOIN footnote_citations AS c ON c.child_note COLLATE BINARY = r.ancestor), originals AS (SELECT r.note_id, r.ancestor FROM reach AS r WHERE NOT EXISTS (SELECT 1 FROM footnote_citations AS c WHERE c.child_note COLLATE BINARY = r.ancestor)), sizes AS (SELECT note_id, COUNT(*) AS original_count FROM originals GROUP BY note_id COLLATE BINARY) SELECT a.note_id AS note_a, b.note_id AS note_b, a.original_count FROM sizes AS a JOIN sizes AS b ON a.note_id COLLATE BINARY < b.note_id AND a.original_count = b.original_count WHERE NOT EXISTS (SELECT ancestor COLLATE BINARY FROM originals WHERE note_id COLLATE BINARY = a.note_id EXCEPT SELECT ancestor COLLATE BINARY FROM originals WHERE note_id COLLATE BINARY = b.note_id) ORDER BY note_a COLLATE BINARY, note_b COLLATE BINARY",
  "decision-cite-active-glaze-inspection-card": "WITH ranked AS (SELECT f.firing_code, f.trial_pits, f.control_pits, c.primary_text, c.allowance, c.card_id, ROW_NUMBER() OVER (PARTITION BY f.firing_code ORDER BY c.start_day DESC, c.card_id COLLATE BINARY DESC) AS revision_rank FROM tile_firings AS f JOIN inspection_cards AS c ON c.finish_code = f.finish_code AND c.start_day <= f.firing_day WHERE f.control_pits IS NOT NULL AND f.trial_pits IS NOT NULL), assessed AS (SELECT firing_code, CASE primary_text WHEN 'Count extra pinholes on the trial tile.' THEN trial_pits - control_pits WHEN 'Count any difference between the tiles.' THEN ABS(trial_pits - control_pits) END AS assessed_difference, allowance, card_id FROM ranked WHERE revision_rank = 1) SELECT firing_code, assessed_difference, allowance, card_id FROM assessed WHERE assessed_difference > allowance ORDER BY firing_code COLLATE BINARY"
}
